    },
    {
      "document_id": "970",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The senator pays tribute to a constituent (Cal Ripken Jr.) and announces the introduction of a resolution. She is not claiming credit for securing federal funds, an agency decision, a realized legislative outcome, or a federal appointment."
    },
    {
      "document_id": "3431",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The senator is expressing no confidence in the Attorney General and explaining his rationale. There is no claim of credit for delivering a desirable outcome or passing legislation."
    },
    {
      "document_id": "3436",
      "label": "1",
      "codebook_rule": [
        "2"
      ],
      "explanation": "The senators are claiming credit for successfully passing the state sales tax deductibility measure in Congress and explicitly mention how they worked to get it through the Senate to benefit Washington families."
    },
    {
      "document_id": "3150",
      "label": "1",
      "codebook_rule": [
        "1"
      ],
      "explanation": "The senator announces that a local partnership in Iowa will receive a $176,000 federal loan from the USDA, effectively claiming credit for the localized funding awarded to his state."
    },
    {
      "document_id": "2089",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The senator gives a speech highlighting bipartisanship, past work, and introducing or advocating for legislation. He does not announce a newly passed legislative outcome, secure federal funds, or claim credit for an agency decision."
    },
    {
      "document_id": "3529",
      "label": "1",
      "codebook_rule": [
        "1",
        "2"
      ],
      "explanation": "The senator announces that he helped to secure $1.5 million in localized federal funding for a specific project in his state, noting its inclusion in the passed Energy and Water Appropriations conference report."
    },
    {
      "document_id": "447",
      "label": "1",
      "codebook_rule": [
        "1"
      ],
      "explanation": "The senator and congressman announce the inclusion of $1.5 million in localized federal funding for a county emergency radio system, explicitly crediting the senator's leadership in securing the funds."
    }
  ]
}

{
  "classifications": [
    {
      "document_id": "1710",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The senator is stating his position and offering commentary on the findings of the Iraq Study Group report. He is not claiming credit for securing federal funds, passing legislation, influencing an agency decision, or making an appointment."
    },
    {
      "document_id": "2201",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The senator is discussing his staff's attendance at a briefing and advocating for better mental health care and future congressional hearings. He is not claiming credit for a specific legislative victory, localized funding, or a concrete policy change."
    },
    {
      "document_id": "1704",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The press release announces the introduction of a new bill (the STAR Act). According to the codebook, introducing legislation is considered position-taking and does not qualify as credit-claiming since no legislative milestone or outcome has been achieved yet."
    },
    {
      "document_id": "2190",
      "label": "1",
      "codebook_rule": [
        "3"
      ],
      "explanation": "The document explicitly states that \"As a result of his efforts the Treasury department issued a moratorium on allowing conversions to go forward in 1999.\" The senator is claiming that his direct intervention successfully resulted in a favorable action/policy change by a federal agency."
    },
    {
      "document_id": "3812",
      "label": "0",
      "codebook_rule": [],
      "explanation": "This press release merely announces Senate committee and subcommittee chair assignments along with their respective jurisdictions. This is an administrative announcement and does not claim credit for funds, legislation, agency decisions, or appointments."
    },
    {
      "document_id": "3195",
      "label": "1",
      "codebook_rule": [
        "1"
      ],
      "explanation": "The senators are announcing that they successfully secured and the Senate Appropriations Committee approved $225,000 in federal funding for a local water system upgrade in the town of Lancaster."
    },
    {
      "document_id": "3688",
      "label": "0",
      "codebook_rule": [],
      "explanation": "The senators are announcing the introduction of the Caribbean National Forest Act. The codebook specifically states that introducing legislation is merely position-taking and does not qualify as claiming credit for a realized legislative outcome."
    },
    {
      "document_id": "3626",
      "label": "1",
      "codebook_rule": [
        "1"
      ],
      "explanation": "The senator is directly announcing the award of a $675,000 federal grant from the U.S. Department of Homeland Security to a local fire department in Fairbanks, which is a textbook example of credit-claiming for federal funding."
    },
    {
      "document_id": "3228",
      "label": "1",
      "codebook_rule": [
        "1",
        "2"
      ],
      "explanation": "The senator claims credit for a specific legislative milestone (his bill passing out of his subcommittee unanimously) and extensively details the specific federal funding amounts and policy initiatives he successfully included within that bill."
    },
    {
      "document_id": "4700",
      "label": "0",
      "codebook_rule": [],
      "explanation": "While the senator notes the benefits of a passed tax cut and mentions her support for it, she does not claim credit for authoring, sponsoring, or championing the legislation. The release is primarily used to criticize the opposing party for the bill's lack of fiscal responsibility and to advocate for future action."
    }
  ]
}

